import { MakeLogicType, afterMount, connect, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { cloudAgentsCatalogRetrieve } from '../generated/api'
import type {
    CloudAgentCatalogApi,
    CloudAgentLimitsApi,
    CloudAgentModelApi,
    CloudAgentRateCardApi,
    CloudAgentSizeApi,
    InferenceModeEnumApi,
} from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cloudAgentsCatalogLogicValues {
    currentProjectId: number | null // projectLogic
    catalog: CloudAgentCatalogApi | null
    catalogLoadFailed: boolean
    catalogLoading: boolean
    inferenceModes: InferenceModeEnumApi[]
    limits: CloudAgentLimitsApi | null
    models: CloudAgentModelApi[]
    rates: CloudAgentRateCardApi | null
    sizes: CloudAgentSizeApi[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cloudAgentsCatalogLogicActions {
    loadCatalog: () => any
    loadCatalogFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCatalogSuccess: (
        catalog: CloudAgentCatalogApi,
        payload?: any
    ) => {
        catalog: CloudAgentCatalogApi
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cloudAgentsCatalogLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        sizes: (catalog: CloudAgentCatalogApi | null) => CloudAgentSizeApi[]
        models: (catalog: CloudAgentCatalogApi | null) => CloudAgentModelApi[]
        inferenceModes: (catalog: CloudAgentCatalogApi | null) => InferenceModeEnumApi[]
        rates: (catalog: CloudAgentCatalogApi | null) => CloudAgentRateCardApi | null
        limits: (catalog: CloudAgentCatalogApi | null) => CloudAgentLimitsApi | null
    }
}

export type cloudAgentsCatalogLogicType = MakeLogicType<
    cloudAgentsCatalogLogicValues,
    cloudAgentsCatalogLogicActions,
    Record<string, any>,
    cloudAgentsCatalogLogicMeta
>

/** The sizes, models, rates and limits. Every price on a Cloud agents page comes from this one load. */
export const cloudAgentsCatalogLogic = kea<cloudAgentsCatalogLogicType>([
    path(['products', 'cloud_agents', 'frontend', 'logics', 'cloudAgentsCatalogLogic']),
    connect(() => ({ values: [projectLogic, ['currentProjectId']] })),
    loaders(({ values }) => ({
        catalog: [
            null as CloudAgentCatalogApi | null,
            {
                loadCatalog: async (): Promise<CloudAgentCatalogApi> =>
                    await cloudAgentsCatalogRetrieve(String(values.currentProjectId)),
            },
        ],
    })),
    reducers({
        catalogLoadFailed: [false, { loadCatalog: () => false, loadCatalogFailure: () => true }],
    }),
    selectors({
        sizes: [
            (s) => [s.catalog],
            (catalog: CloudAgentCatalogApi | null): CloudAgentSizeApi[] => catalog?.sizes ?? [],
        ],
        models: [
            (s) => [s.catalog],
            (catalog: CloudAgentCatalogApi | null): CloudAgentModelApi[] => catalog?.models ?? [],
        ],
        inferenceModes: [
            (s) => [s.catalog],
            (catalog: CloudAgentCatalogApi | null): InferenceModeEnumApi[] => catalog?.inference_modes ?? [],
        ],
        rates: [
            (s) => [s.catalog],
            (catalog: CloudAgentCatalogApi | null): CloudAgentRateCardApi | null => catalog?.rates ?? null,
        ],
        limits: [
            (s) => [s.catalog],
            (catalog: CloudAgentCatalogApi | null): CloudAgentLimitsApi | null => catalog?.limits ?? null,
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadCatalog()
    }),
])
